[ -d mech ] || exit 0; find mech -maxdepth 4 -type f \( -iname '*.step' -o -iname '*.stp' -o -iname '*.sc' -o -iname '*.solidcraft' -o -iname '*.iges' -o -iname '*.igs' -o -iname '*.stl' -o -iname '*.3mf' -o -iname '*.obj' -o -iname '*.glb' -o -iname '*.png' \) -not -path '*/.*' 2>/dev/null | LC_ALL=C sort | head -n 400 | while IFS= read -r f; do cksum "$f"; done